function sinavHavuz(){if(d.metinTur==='cikmis'&&CIKMIS.length){var gg={},ll=[];CIKMIS.forEach(function(x){if(!gg[x.m]){gg[x.m]=1;ll.push(x.m);}});return ll;}return d.metinTur==='genel'?GENELMETIN:(d.metinTur==='adliye'?METINLER:GENELMETIN.concat(METINLER));}
function bicimle(m){if(d.bicim!=='resmi')return m;return m.toLocaleLowerCase('tr').replace(/â/g,'a').replace(/î/g,'i').replace(/û/g,'u').replace(/[-–—]/g,' ').replace(/[^a-zçğıöşü0-9\s]/g,'').replace(/\s+/g,' ').trim();}
function metinUret(tur){
 if(tur==='sinav'){var sira=karistir(sinavHavuz()).slice(0,4),w=[];sira.forEach(function(m){w=w.concat(bicimle(m).split(/\s+/));});return w;}
 var havuz=tur==='sinavsik'?SIKSINAV:tur==='hukuk'?HUKUK:(tur==='karma'?GENEL.concat(HUKUK):GENEL),w2=[];
 for(var i=0;i<900;i++)w2.push(havuz[Math.floor(Math.random()*havuz.length)]);return w2;
}
function dersUret(harfler){var w=[];for(var i=0;i<600;i++){var n=2+Math.floor(Math.random()*4),s='';for(var j=0;j<n;j++)s+=harfler.charAt(Math.floor(Math.random()*harfler.length));w.push(s);}return w;}
function basla(ayar){
 sonSb=null;sonAyar=ayar;durdur();
 o={kelimeler:ayar.kelimeler(),i:0,dogru:0,yanlis:0,vurus:0,dogruVurus:0,sure:ayar.sure,basla:0,bitti:false,tusHata:{},yanlisKelime:[],ad:ayar.ad,sinav:!!ayar.sinav,rakip:ayar.rakip||0,kazandi:null};
 $('yaris').hidden=!o.rakip;
 $('calisBaslik').textContent=ayar.ad;
 $('metin').innerHTML=o.kelimeler.map(function(k,i){return '<span id="k'+i+'">'+esc(k)+'</span>';}).join(' ');
 $('metin').scrollTop=0;
 $('giris').disabled=false;$('giris').value='';sesDugmeYaz();
 isaretle();sayacCiz();goster('calis');$('giris').focus();
}
function isaretle(){var e=$('k'+o.i);if(!e)return;e.className='simdi';var m=$('metin');m.scrollTop=Math.max(0,e.offsetTop-70);}
function gecen(){return o.basla?(Date.now()-o.basla)/1000:0;}
function sayacCiz(){
 var g=gecen(),kalan=o.sure-g;
 $('cSure').textContent=sureYaz(kalan);$('cDogru').textContent=o.dogru;$('cYanlis').textContent=o.yanlis;
 $('cDks').textContent=g>2?Math.round(o.dogru/(g/60)):0;
 var t=o.dogru+o.yanlis;$('cAcc').textContent='%'+(t?Math.round(o.dogru*100/t):100);
 if(o.rakip){var N=o.kelimeler.length;$('yBen').style.width=Math.min(100,o.i*100/N)+'%';$('yRakip').style.width=Math.min(100,g*o.rakip/60*100/N)+'%';}
}
function tik(){if(!o||o.bitti)return;if(o.rakip&&gecen()*o.rakip/60>=o.kelimeler.length){o.kazandi=false;sayacCiz();bitir();return;}if(gecen()>=o.sure){bitir();return;}sayacCiz();}
function onayla(yazilan){
 var bek=o.kelimeler[o.i],e=$('k'+o.i);
 o.vurus+=yazilan.length+1;
 if(yazilan===bek){o.dogru++;o.dogruVurus+=bek.length+1;e.className='dogru';}
 else{o.yanlis++;e.className='yanlis';o.yanlisKelime.push(bek);
  for(var j=0;j<bek.length;j++){if(yazilan.charAt(j)!==bek.charAt(j)){var h=bek.charAt(j).toLocaleLowerCase('tr');o.tusHata[h]=(o.tusHata[h]||0)+1;}}
  if(o.rakip){e.className='simdi hata';sayacCiz();return;}}
 o.i++;
 if(o.i>=o.kelimeler.length){if(o.rakip)o.kazandi=true;sayacCiz();bitir();return;}
 isaretle();sayacCiz();
}
$('giris').addEventListener('input',function(){
 if(!o||o.bitti)return;
 if(!o.basla&&this.value.trim()){o.basla=Date.now();zamanlayici=setInterval(tik,200);}
 var v=this.value;
 if(/\s$/.test(v)){var y=v.trim();this.value='';if(y)onayla(y);return;}
 var e=$('k'+o.i);if(e)e.classList.toggle('hata',o.kelimeler[o.i].indexOf(v)!==0);
});
function bitir(){
 if(!o||o.bitti)return;o.bitti=true;durdur();$('giris').disabled=true;
 var g=Math.min(o.sure,Math.max(1,gecen())),dk=g/60,t=o.dogru+o.yanlis;
 var s={t:Date.now(),ad:o.ad,sinav:o.sinav,sure:Math.round(g),dogru:o.dogru,yanlis:o.yanlis,dks:Math.round(o.dogru/dk),vurus:o.vurus,acc:t?Math.round(o.dogru*100/t):0};
 if(o.rakip)s.yaris={k:o.kazandi,h:o.rakip};
 if(t>0){d.gecmis.push(s);gunEkle(s.sure);if(d.gecmis.length>200)d.gecmis=d.gecmis.slice(-200);
  o.yanlisKelime.forEach(function(k){d.hatali[k]=(d.hatali[k]||0)+1;});
  for(var kk in o.tusHata)d.tus[kk]=(d.tus[kk]||0)+o.tusHata[kk];
  var an=Object.keys(d.hatali);if(an.length>300){an.sort(function(a,b){return d.hatali[a]-d.hatali[b];}).slice(0,an.length-300).forEach(function(k){delete d.hatali[k];});}
  kaydet();}
 sonucCiz(s);
}
function sonucCiz(s){
 $('sBaslik').textContent=s.ad+' — Sonuç';$('sInceleme').hidden=true;
 var r='';
 if(s.sinav){var tam=s.sure>=d.sure*60-1;
  if(!tam)r='<span class="rozet no">Süre dolmadan bitirildi; baraj değerlendirmesi yapılmadı</span>';
  else{var tt=s.dogru+s.yanlis,oran=tt?Math.round(s.yanlis*100/tt):0;
   if(s.atlanan>=22)r='<span class="rozet no">Başarısız: '+s.atlanan+' kelime atlandı (sınır 22)</span>';
   else if(oran>25)r='<span class="rozet no">Başarısız: yanlış kelime oranı %'+oran+' (sınır %25)</span>';
   else r=s.dogru>=d.baraj?'<span class="rozet ok">Baraj geçildi: '+s.dogru+' / '+d.baraj+' doğru kelime, hata oranı %'+oran+'</span>':'<span class="rozet no">Barajın altında: '+s.dogru+' / '+d.baraj+' doğru kelime</span>';}}
 if(s.yaris){if(s.yaris.k===true)r='<span class="rozet ok">Kazandınız! Rakip hızı: '+s.yaris.h+' kelime/dk</span>';else if(s.yaris.k===false)r='<span class="rozet no">Rakip önce bitirdi ('+s.yaris.h+' kelime/dk)</span>';}
 $('sRozet').innerHTML=r;
 var kh='';$('sKutular').hidden=false;
 if(s.sinav){var tam2=s.sure>=d.sure*60-1,tt2=s.dogru+s.yanlis,or2=tt2?s.yanlis*100/tt2:0,hv=0,kx;for(kx in o.tusHata)hv+=o.tusHata[kx];
  var ks=[['En az '+d.baraj+' doğru kelime',s.dogru+' doğru kelime',s.dogru>=d.baraj],['Yanlış kelime oranı en çok %25','%'+or2.toFixed(1).replace('.',','),or2<=25]];
  if(s.atlanan!==undefined)ks.push(['En çok 21 atlanan kelime',s.atlanan+' atlanan kelime',s.atlanan<22]);
  var gecti=ks.every(function(x){return x[2];}),neden=ks.filter(function(x){return !x[2];}).map(function(x){return x[0].toLocaleLowerCase('tr');}).join('; ');
  kh+=!tam2?'<div class="karar bilgi"><b>Süre dolmadan bitirildi</b><span>Aşağıdaki değerlendirme bilgi amaçlıdır; gerçek sınavda süre sonuna kadar yazılır.</span></div>'
   :gecti?'<div class="karar ok"><b>BAŞARILI</b><span>Bu sonuçla uygulamalı sınav barajını geçerdiniz. Barajın '+(s.dogru-d.baraj)+' kelime üzerindesiniz.</span></div>'
   :'<div class="karar no"><b>BAŞARISIZ</b><span>Sağlanmayan koşul: '+esc(neden)+'.</span></div>';
  kh+='<p class="soluk" style="margin:-6px 0 10px">'+esc(TURAD[s.tur||d.sinavTur]||TURAD.zabit)+' uygulamalı sınavı kurallarına göre değerlendirildi: 3 dakikada en az '+d.baraj+' doğru kelime, yanlış kelime oranı en çok %25, en çok 21 atlanan kelime.</p>';
  kh+='<div class="kosul">'+ks.map(function(x){return '<div class="'+(x[2]?'':'no')+'">'+esc(x[0])+'<b>'+esc(x[1])+'</b><i>'+(x[2]?'✓ Sağlandı':'✗ Sağlanmadı')+'</i></div>';}).join('')+'</div>';
  var dkv=s.sure?Math.round(s.vurus/(s.sure/60)):0;
  kh+='<div class="hesap"><div><h3>Kelime hesabı (kâtiplik sınavı)</h3><table>'+
   '<tr><td>Dakikada doğru kelime</td><td>'+s.dks+'</td></tr><tr><td>Toplam yazılan kelime</td><td>'+tt2+'</td></tr><tr><td>Doğru yazılan kelime</td><td>'+s.dogru+'</td></tr><tr><td>Yanlış yazılan kelime</td><td>'+s.yanlis+'</td></tr>'+
   (s.atlanan!==undefined?'<tr><td>Atlanan kelime</td><td>'+s.atlanan+'</td></tr>':'')+'<tr><td>Yanlış kelime oranı</td><td>%'+or2.toFixed(1).replace('.',',')+'</td></tr></table></div>'+
   '<div><h3>Vuruş hesabı (bilgi amaçlı)</h3><table><tr><td>Toplam tuş vuruşu</td><td>'+s.vurus+'</td></tr><tr><td>Dakikada vuruş</td><td>'+dkv+'</td></tr><tr><td>Hatalı vuruş</td><td>'+hv+'</td></tr>'+
   '<tr><td>Vuruş hata oranı</td><td>%'+(s.vurus?(hv*100/s.vurus).toFixed(1).replace('.',','):'0')+'</td></tr><tr><td>Sınav süresi</td><td>'+sureYaz(s.sure)+'</td></tr><tr><td>İmla durumu</td><td>'+esc(s.imla||(d.bicim==='resmi'?'İmlasız':'İmlalı'))+'</td></tr></table></div></div>';
  if(tam2&&d.sure===3){var yt=TABAN26.filter(function(x){return s.dogru>=x[1];}).length;kh+='<p class="soluk">Bu kelime sayısıyla 2026 alımında '+TABAN26.length+' adliyenin <b>'+yt+'</b> tanesine girebilirdiniz (resmî olmayan veriye göre). <a href="#" data-git="taban">Hangi adliyeler? Listeye bak</a></p>';tabanSon=s.dogru;}
  $('sRozet').innerHTML='';$('sKutular').hidden=true;}
 $('sKarne').innerHTML=kh;
 $('sKutular').innerHTML='<div>Doğru kelime<b>'+s.dogru+'</b></div><div>Yanlış kelime<b>'+s.yanlis+'</b></div><div>Dakikada kelime<b>'+s.dks+'</b></div><div>Doğruluk<b>%'+s.acc+'</b></div><div>Toplam vuruş<b>'+s.vurus+'</b></div><div>Süre<b>'+sureYaz(s.sure)+'</b></div>'+(s.atlanan!==undefined?'<div>Atlanan kelime<b>'+s.atlanan+'</b></div>':'');
 var en=0,k;for(k in o.tusHata)en=Math.max(en,o.tusHata[k]);
 $('sHarita').innerHTML=DUZEN[d.klavye].map(function(sira){return '<div class="sira">'+sira.split('').map(function(h){var n=o.tusHata[h]||0,st='';
  if(n){var a=0.25+0.75*n/en;st=' style="background:rgba(210,45,35,'+a.toFixed(2)+');color:#fff;border-color:transparent"';}
  return '<div class="tus"'+st+'>'+esc(h.toLocaleUpperCase('tr'))+(n?'<small>'+n+'</small>':'')+'</div>';}).join('')+'</div>';}).join('');
 var u={};o.yanlisKelime.forEach(function(x){u[x]=1;});var l=Object.keys(u);
 $('sKelimeler').innerHTML=l.length?l.map(function(x){return '<span>'+esc(x)+'</span>';}).join(''):'<span>Yanlış yazılan kelime yok.</span>';
 goster('sonucS');
}
function hataCalis(tekrar){
 var l=Object.keys(d.hatali);if(!l.length){alert('Henüz hatalı kelime birikmedi.');return;}
 basla({ad:'Hatalı Kelime Çalışması',sure:120,kelimeler:function(){var w=[];for(var i=0;i<tekrar;i++)w=w.concat(karistir(l));return w;}});
}
function anaCiz(){
 var g=d.gecmis,son=g[g.length-1],en=0;g.forEach(function(x){en=Math.max(en,x.dks);});
 $('ozet').innerHTML='<div>Deneme sayısı<b>'+g.length+'</b></div><div>En iyi (dakikada kelime)<b>'+en+'</b></div><div>Son deneme<b>'+(son?son.dks:'—')+'</b></div><div>Biriken hatalı kelime<b>'+Object.keys(d.hatali).length+'</b></div>';
 kutupCiz();hedefYaz();var gg=gunDurum();$('anaHedef').innerHTML+='<br>Bugün <b>'+gg.dk+' / '+GUNHEDEF+' dakika</b> çalıştınız'+(gg.seri>1?' · <b>'+gg.seri+' gün</b> üst üste':'')+'.';
}
function hedefYaz(){var sn=d.gecmis.filter(function(x){return x.sinav;}).slice(-5),ort=0,ger=Math.ceil(d.baraj/d.sure);sn.forEach(function(x){ort+=x.dks;});ort=sn.length?Math.round(ort/sn.length):0;
 var t='Baraj için dakikada <b>'+ger+' kelime</b> gerekir. ';t+=ort?'Son sınav denemelerinizin ortalaması <b>'+ort+'</b>.':'Henüz sınav denemeniz yok.';
 if(d.sinavTarih){var p=d.sinavTarih.split('-'),g=Math.round((new Date(Number(p[0]),Number(p[1])-1,Number(p[2]))-new Date(new Date().setHours(0,0,0,0)))/86400000);if(g>=0)t+=' Sınava <b>'+g+' gün</b> kaldı.';}
 $('anaHedef').innerHTML=t;}
