function dersCiz(){
 var h=DERSLER[d.klavye].map(function(x,i){return '<button class="secenek" data-ders="'+i+'"><b>'+(i+1)+'. '+esc(x[0])+'</b><span class="soluk">'+esc(x[1].split('').join(' '))+'</span></button>';}).join('');
 h+='<button class="secenek" data-ders="hukuk"><b>'+(DERSLER[d.klavye].length+1)+'. Hukuk terimleri</b><span class="soluk">mahkeme, tutanak, tebligat, bilirkişi…</span></button>';
 h+='<button class="secenek" data-ders="rakam"><b>'+(DERSLER[d.klavye].length+2)+'. Rakam ve sayı çalışması</b><span class="soluk">2 ile 7 haneli sayılar: 47, 1926, 305814…</span></button>';
 $('dersler').innerHTML=h;
}
function hataCiz(){
 var l=Object.keys(d.hatali).sort(function(a,b){return d.hatali[b]-d.hatali[a];});
 tusCiz();
 $('hataListe').innerHTML=l.length?l.map(function(x){return '<span>'+esc(x)+' <small class="soluk">×'+d.hatali[x]+'</small></span>';}).join(''):'<span>Liste boş.</span>';
}
function istCiz(){
 var g=d.gecmis,en=0,top=0;g.forEach(function(x){en=Math.max(en,x.dks);top+=x.dks;});
 var sn=g.filter(function(x){return x.sinav;}),gecen=sn.filter(function(x){var tt=x.dogru+x.yanlis;return x.dogru>=d.baraj&&x.yanlis*100<=25*tt;}).length;
 $('istKutular').innerHTML='<div>Deneme<b>'+g.length+'</b></div><div>En iyi<b>'+en+'</b></div><div>Ortalama<b>'+(g.length?Math.round(top/g.length):0)+'</b></div><div>Sınav denemesi<b>'+sn.length+'</b></div><div>Barajı geçen<b>'+gecen+'</b></div>';
 var son=g.slice(-30),W=1000,H=220,P=34;
 if(son.length<2){$('grafik').innerHTML='<p class="soluk">Grafik için en az iki deneme gerekir.</p>';}
 else{var mx=Math.max.apply(null,son.map(function(x){return x.dks;}).concat([d.baraj/d.sure]))*1.15||1;
  var X=function(i){return P+i*(W-2*P)/(son.length-1);},Y=function(v){return H-P-v*(H-2*P)/mx;};
  var pts=son.map(function(x,i){return X(i).toFixed(1)+','+Y(x.dks).toFixed(1);}).join(' ');
  var by=Y(d.baraj/d.sure);
  $('grafik').innerHTML='<svg viewBox="0 0 '+W+' '+H+'" width="100%" role="img" aria-label="Dakikada kelime grafiği"><line x1="'+P+'" y1="'+(H-P)+'" x2="'+(W-P)+'" y2="'+(H-P)+'" stroke="#9aa6b5"/>'+
   '<line x1="'+P+'" y1="'+by+'" x2="'+(W-P)+'" y2="'+by+'" stroke="#d2a000" stroke-dasharray="6 5"/><text x="'+(P+4)+'" y="'+(by-5)+'">baraj hızı ('+Math.round(d.baraj/d.sure)+' kelime/dk)</text>'+
   '<polyline points="'+pts+'" fill="none" stroke="#1d5fa8" stroke-width="3"/>'+son.map(function(x,i){return '<circle cx="'+X(i)+'" cy="'+Y(x.dks)+'" r="4" fill="#1d5fa8"/>';}).join('')+
   '<text x="'+P+'" y="14">dakikada doğru kelime — son '+son.length+' deneme</text></svg>';}
 var h='<tr><th>Tarih</th><th>Çalışma</th><th>Süre</th><th>Doğru</th><th>Yanlış</th><th>Kelime/dk</th><th>Doğruluk</th></tr>';
 g.slice(-25).reverse().forEach(function(x){h+='<tr><td>'+new Date(x.t).toLocaleString('tr-TR')+'</td><td>'+esc(x.ad)+'</td><td>'+sureYaz(x.sure)+'</td><td>'+x.dogru+'</td><td>'+x.yanlis+'</td><td><b>'+x.dks+'</b></td><td>%'+x.acc+'</td></tr>';});
 if(!g.length)h+='<tr><td colspan="7">Henüz deneme yok.</td></tr>';
 $('istTablo').innerHTML=h;
}
function ayarCiz(){$('aKlavye').value=d.klavye;$('aSure').value=d.sure;$('aBaraj').value=d.baraj;$('aTema').value=d.tema;}
function temaUygula(){var k=d.tema==='koyu';document.body.classList.toggle('koyu',k);[].forEach.call(document.querySelectorAll('.temaD'),function(b){b.textContent=k?'☀ Aydınlık mod':'☾ Karanlık mod';});}
function temaDegis(){d.tema=d.tema==='koyu'?'acik':'koyu';d.temaV=1;kaydet();temaUygula();if(!$('ayar').hidden)ayarCiz();}


var _tum=null;
function tumKelime(){if(_tum)return _tum;var u={};METINLER.concat(GENELMETIN).forEach(function(m){m.toLocaleLowerCase('tr').replace(/â/g,'a').replace(/î/g,'i').replace(/û/g,'u').replace(/[^a-zçğıöşü\s]/g,' ').split(/\s+/).forEach(function(k){if(k.length>1)u[k]=1;});});
 GENEL.concat(HUKUK).forEach(function(k){if(k.indexOf(' ')<0)u[k.replace(/â/g,'a')]=1;});_tum=Object.keys(u);return _tum;}
function haritaHtml(kayit){var en=0,k;for(k in kayit)en=Math.max(en,kayit[k]);
 return DUZEN[d.klavye].map(function(sira){return '<div class="sira">'+sira.split('').map(function(h){var n=kayit[h]||0,st='';
  if(n){var a=0.25+0.75*n/en;st=' style="background:rgba(210,45,35,'+a.toFixed(2)+');color:#fff;border-color:transparent"';}
  return '<div class="tus"'+st+'>'+esc(h.toLocaleUpperCase('tr'))+(n?'<small>'+n+'</small>':'')+'</div>';}).join('')+'</div>';}).join('');}
function zayifTus(){return Object.keys(d.tus).filter(function(k){return /^[a-zçğıöşü]$/.test(k);}).sort(function(a,b){return d.tus[b]-d.tus[a];}).slice(0,5);}
function tusCiz(){$('tusHarita').innerHTML=haritaHtml(d.tus);var z=zayifTus();$('tusBilgi').textContent=z.length?'En zayıf tuşlar: '+z.map(function(x){return x.toLocaleUpperCase('tr');}).join(', '):'Henüz tuş hatası kaydı yok.';}
